package ru.kstolu.app;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;import android.text.InputFilter;import org.json.*;import java.util.*;import java.util.concurrent.*;import java.util.function.*;
/** Recipe-scoped sheet. Context is captured at send time; opening a sheet is never a paid call. */
final class SousChefSheet {
 private final Activity host;private final JSONObject item;private final IntSupplier step;private final LongSupplier timer;private final SharedPreferences store;private final String key;private final Handler ui=new Handler(Looper.getMainLooper());
 private Dialog dialog;private LinearLayout messages;private ScrollView scroll;private EditText input;private Button send;private TextView status,context;private CheckBox consent;private JSONArray history;private boolean busy=false,retryWarning=false;
 SousChefSheet(Activity a,JSONObject snapshot,IntSupplier currentStep,LongSupplier timerSeconds)throws Exception{host=a;item=new JSONObject(snapshot.toString());step=currentStep;timer=timerSeconds;store=a.getSharedPreferences("sous-chef",0);key=Library.id(item.getJSONObject("recipe"));history=new JSONArray(store.getString(key,"[]"));}
 private int dp(int v){return Math.round(v*host.getResources().getDisplayMetrics().density);}
 private GradientDrawable bg(int c,int radius){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(dp(radius));g.setStroke(dp(1),0xffdfe6d8);return g;}
 private TextView text(String t,int size,boolean bold){TextView v=new TextView(host);v.setText(t);v.setTextSize(size);v.setTextColor(0xff253127);if(bold)v.setTypeface(null,Typeface.BOLD);v.setLineSpacing(dp(3),1);return v;}
 private Button button(String label,Runnable run){Button b=new Button(host);b.setText(label);b.setAllCaps(false);b.setTextColor(0xff4c6441);b.setMinHeight(dp(48));b.setBackground(bg(Color.WHITE,12));b.setOnClickListener(v->run.run());return b;}
 void show(){
  dialog=new Dialog(host);dialog.setTitle("Су-шеф");LinearLayout root=new LinearLayout(host);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(20),dp(12),dp(20),dp(16));root.setBackground(bg(0xfff7f9f3,24));androidx.core.view.ViewCompat.setAccessibilityPaneTitle(root,"Су-шеф: вопросы по рецепту");
  TextView handle=text("────",14,false);handle.setGravity(Gravity.CENTER);root.addView(handle);
  LinearLayout header=new LinearLayout(host);header.setGravity(Gravity.CENTER_VERTICAL);header.addView(text("Су-шеф",25,true),new LinearLayout.LayoutParams(0,-2,1));header.addView(button("⋯",this::clearConversation),new LinearLayout.LayoutParams(dp(48),dp(48)));header.addView(button("Закрыть",()->dialog.dismiss()));root.addView(header);
  JSONObject r=item.optJSONObject("recipe");context=text(r.optString("title")+"\n"+item.optInt("portions",r.optInt("servings",2))+" порц. · шаг "+Math.min(step.getAsInt()+1,r.optJSONArray("steps").length())+" / "+r.optJSONArray("steps").length(),14,false);context.setPadding(dp(12),dp(12),dp(12),dp(12));context.setBackground(bg(0xffeaf0e4,12));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.setMargins(0,dp(12),0,dp(8));root.addView(context,cp);
  scroll=new ScrollView(host);messages=new LinearLayout(host);messages.setOrientation(LinearLayout.VERTICAL);scroll.addView(messages);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
  HorizontalScrollView chips=new HorizontalScrollView(host);chips.setHorizontalScrollBarEnabled(false);LinearLayout choices=new LinearLayout(host);for(String label:new String[]{"Чем заменить?","Объясни этот шаг","Что-то пошло не так"}){Button b=button(label,()->{if(!busy)input.setText(label);});LinearLayout.LayoutParams x=new LinearLayout.LayoutParams(-2,dp(44));x.setMargins(0,0,dp(6),0);choices.addView(b,x);}chips.addView(choices);root.addView(chips);
  consent=new CheckBox(host);consent.setText("Передать рецепт и сообщения в AnyModel и DeepSeek");consent.setTextSize(14);consent.setChecked(store.getBoolean("consent",false));consent.setOnCheckedChangeListener((b,checked)->store.edit().putBoolean("consent",checked).apply());root.addView(consent);
  status=text("Советы ИИ могут ошибаться. Рецепт сам не изменяется.",14,false);status.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);root.addView(status);
  LinearLayout compose=new LinearLayout(host);compose.setGravity(Gravity.BOTTOM);input=new EditText(host);input.setTextSize(16);input.setHint("Спросить о рецепте…");input.setContentDescription("Вопрос Су-шефу");input.setMinLines(1);input.setMaxLines(3);input.setFilters(new InputFilter[]{new InputFilter.LengthFilter(1200)});input.setBackground(bg(Color.WHITE,12));input.setPadding(dp(12),dp(8),dp(12),dp(8));compose.addView(input,new LinearLayout.LayoutParams(0,-2,1));send=button("↑",()->submit());send.setContentDescription("Отправить вопрос");send.setTextColor(Color.WHITE);send.setBackground(bg(0xff4c6441,12));LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(dp(48),dp(48));sp.leftMargin=dp(8);compose.addView(send,sp);root.addView(compose);
  dialog.setContentView(root);Window w=dialog.getWindow();if(w!=null){w.setBackgroundDrawableResource(android.R.color.transparent);w.setGravity(Gravity.BOTTOM);w.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);}
  if(host.getResources().getConfiguration().orientation==android.content.res.Configuration.ORIENTATION_LANDSCAPE){chips.setVisibility(View.GONE);handle.setVisibility(View.GONE);}dialog.show();if(w!=null)w.setLayout(-1,(int)(host.getResources().getDisplayMetrics().heightPixels*.84));render();
  String pending=store.getString(key+":pending",null);if(pending!=null)recover(pending);
 }
 private void clearConversation(){if(busy){status.setText("Дождитесь ответа перед очисткой.");return;}new AlertDialog.Builder(host).setTitle("Очистить переписку блюда?").setMessage("Локальная история и незавершённый вопрос будут удалены. Это не отменяет запрос у поставщика и не удаляет серверный кеш раньше срока.").setNegativeButton("Отмена",null).setPositiveButton("Очистить",(d,w)->{history=new JSONArray();store.edit().remove(key).remove(key+":pending").apply();retryWarning=false;input.setText("");render();status.setText("Переписка очищена на этом устройстве.");}).show();}
 private void render(){messages.removeAllViews();if(history.length()==0){TextView empty=text("Я помогу с этим блюдом: объясню шаг, предложу замену или подскажу, что делать, если что-то не получилось.",16,false);empty.setPadding(0,dp(18),0,dp(18));messages.addView(empty);}for(int i=0;i<history.length();i++){JSONObject m=history.optJSONObject(i);boolean user=m.optString("role").equals("user");TextView t=text((user?"Вы\n":"Су-шеф\n")+m.optString("content"),15,false);t.setTextIsSelectable(true);t.setPadding(dp(14),dp(12),dp(14),dp(12));t.setBackground(bg(user?0xffeaf0e4:Color.WHITE,16));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(user?dp(36):0,dp(8),user?0:dp(24),dp(4));messages.addView(t,p);}scroll.post(()->scroll.fullScroll(View.FOCUS_DOWN));}
 private JSONArray boundedHistory()throws Exception{ArrayList<JSONObject> last=new ArrayList<>();int total=0;for(int i=history.length()-1;i>=0&&last.size()<10;i--){JSONObject m=history.getJSONObject(i);int n=m.optString("content").length();if(total+n>14000)break;last.add(0,m);total+=n;}JSONArray a=new JSONArray();for(JSONObject m:last)a.put(m);return a;}
 private void setBusy(boolean value){busy=value;send.setEnabled(!value);input.setEnabled(!value);consent.setEnabled(!value);}
 private void submit(){if(busy)return;String q=input.getText().toString().trim();if(q.isEmpty())return;if(!consent.isChecked()){status.setText("Нужно согласие на передачу рецепта и сообщений.");return;}if(retryWarning){new AlertDialog.Builder(host).setTitle("Отправить новый запрос?").setMessage("Предыдущий запрос мог быть оплачен. Новый вопрос — отдельное обращение к ИИ.").setNegativeButton("Отмена",null).setPositiveButton("Отправить",(d,w)->{retryWarning=false;submit();}).show();return;}
  try{JSONObject payload=new JSONObject().put("requestId",UUID.randomUUID().toString()).put("consent",true).put("recipe",item.getJSONObject("recipe")).put("currency",item.optString("currency","RUB")).put("portions",item.optInt("portions",item.getJSONObject("recipe").optInt("servings",2))).put("step",Math.min(step.getAsInt(),item.getJSONObject("recipe").getJSONArray("steps").length())).put("timerSeconds",timer.getAsLong()).put("message",q).put("history",boundedHistory());store.edit().putString(key+":pending",payload.toString()).commit();setBusy(true);status.setText("Су-шеф отвечает…");ExecutorService worker=Executors.newSingleThreadExecutor();worker.execute(()->{try{JSONObject out=ApiClient.call("/api/chat",payload);ui.post(()->accept(payload,out.optString("reply")));}catch(Exception e){ui.post(()->{setBusy(false);retryWarning=true;status.setText(e.getMessage()+" Вопрос сохранён. Повтор не отправлен.");});}finally{worker.shutdown();}});}catch(Exception e){status.setText("Не удалось подготовить вопрос. Текст не удалён.");}}
 private void accept(JSONObject payload,String reply){try{history.put(new JSONObject().put("role","user").put("content",payload.getString("message")));history.put(new JSONObject().put("role","assistant").put("content",reply));while(history.length()>20)history.remove(0);store.edit().putString(key,history.toString()).remove(key+":pending").apply();input.setText("");retryWarning=false;setBusy(false);render();status.setText("Ответ относится к отправленному рецепту и шагу. Изменения не применены.");}catch(Exception e){status.setText("Не удалось сохранить ответ. Не отправляйте вопрос повторно.");}}
 private void recover(String saved){try{JSONObject payload=new JSONObject(saved);input.setText(payload.optString("message"));setBusy(true);status.setText("Проверяем прежний ответ — без нового запроса к ИИ…");ExecutorService worker=Executors.newSingleThreadExecutor();worker.execute(()->{try{JSONObject out=ApiClient.call("/api/chat-status/"+payload.optString("requestId"),null);ui.post(()->{if(out.optString("status").equals("done"))accept(payload,out.optString("reply"));else{setBusy(false);retryWarning=true;status.setText(out.optString("status").equals("pending")?"Прежний запрос ещё выполняется. Закройте и откройте Су-шефа позже, чтобы получить ответ.":"Прежний ответ не найден. Новый запрос — только с вашим подтверждением.");}});}catch(Exception e){ui.post(()->{setBusy(false);retryWarning=true;status.setText("Не удалось проверить прежний ответ. Автоповтор выключен.");});}finally{worker.shutdown();}});}catch(Exception e){status.setText("Не удалось прочитать прежний вопрос.");}}
}
